const 剥离规则 = [
    /<update(?:variable)?\b[^>]*>[\s\S]*?<\/update(?:variable)?>/gi,
    /<update(?:variable)?\b[^>]*>[\s\S]*$/gi,
    /<\/update(?:variable)?>/gi,
    /<initvar\b[^>]*>[\s\S]*?<\/initvar>/gi,
    /<\/initvar>/gi,
    /<StatusPlaceHolderImpl\s*\/?>/gi,
    /<StatusPlaceHolder\b[^>]*\/?>/gi,
];
export function 清洗正文(原文) {
    let 文本 = 原文 ?? '';
    for (const 规则 of 剥离规则) {
        文本 = 文本.replace(规则, '');
    }
    // 流式到一半的残缺标签
    文本 = 文本.replace(/<[^>\s]*$/, '');
    return 文本
        .replace(/[ \t]+\n/g, '\n')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
}
/** 长聊天里每两秒把所有楼层重新洗一遍太浪费, 按原文做一层记忆 */
const 清洗缓存 = new Map();
function 取清洗结果(id, 原文) {
    const 命中 = 清洗缓存.get(id);
    if (命中 && 命中.原文 === 原文) {
        return 命中.结果;
    }
    const 结果 = 清洗正文(原文);
    清洗缓存.set(id, { 原文, 结果 });
    return 结果;
}
export function 读取剧情() {
    let 消息 = [];
    try {
        消息 = getChatMessages('0-{{lastMessageId}}', { hide_state: 'unhidden' });
    }
    catch {
        return [];
    }
    const 还在的楼层 = new Set(消息.map(条目 => 条目.message_id));
    for (const id of Array.from(清洗缓存.keys())) {
        if (!还在的楼层.has(id)) {
            清洗缓存.delete(id);
        }
    }
    return 消息
        .filter(条目 => 条目.role === 'assistant' || 条目.role === 'user')
        .map(条目 => ({
        id: 条目.message_id,
        role: 条目.role,
        text: 取清洗结果(条目.message_id, 条目.message),
    }))
        .filter(条目 => Boolean(条目.text));
}
/**
 * 剧情只读不写; 刷新靠酒馆事件, 轮询只做兜底.
 */
export function useStory() {
    const 剧情 = ref([]);
    const 流式正文 = ref('');
    const 刷新剧情 = () => {
        剧情.value = 读取剧情();
    };
    // 有的版本推的是累积全文, 有的推的是增量片段, 两种都接住
    const 收流式片段 = (片段) => {
        const 文本 = 片段 ?? '';
        if (!文本) {
            return;
        }
        const 当前 = 流式正文.value;
        if (!当前 || 文本.length > 当前.length || 文本.includes(当前)) {
            流式正文.value = 文本;
        }
        else {
            流式正文.value = 当前 + 文本;
        }
    };
    const 清空流式 = () => {
        流式正文.value = '';
    };
    刷新剧情();
    const 停止监听 = [
        tavern_events.MESSAGE_RECEIVED,
        tavern_events.MESSAGE_SENT,
        tavern_events.MESSAGE_UPDATED,
        tavern_events.MESSAGE_SWIPED,
        tavern_events.MESSAGE_DELETED,
        tavern_events.CHAT_CHANGED,
    ].map(事件 => eventOn(事件, 刷新剧情));
    停止监听.push(eventOn(tavern_events.GENERATION_STARTED, 清空流式), eventOn(tavern_events.GENERATION_ENDED, () => {
        清空流式();
        刷新剧情();
    }), eventOn(tavern_events.GENERATION_STOPPED, () => {
        清空流式();
        刷新剧情();
    }), eventOn(tavern_events.STREAM_TOKEN_RECEIVED, 收流式片段));
    try {
        if (typeof iframe_events !== 'undefined') {
            停止监听.push(eventOn(iframe_events.STREAM_TOKEN_RECEIVED_FULLY, 收流式片段), eventOn(iframe_events.GENERATION_ENDED, 清空流式));
        }
    }
    catch {
        // 没有 iframe 事件就只靠酒馆原生流式
    }
    const 轮询 = window.setInterval(刷新剧情, 2000);
    onUnmounted(() => {
        window.clearInterval(轮询);
        停止监听.forEach(句柄 => 句柄.stop());
    });
    return { 剧情, 流式正文, 刷新剧情 };
}
