import { createScriptIdDiv } from '@util/script';
import App from '../../界面/常驻面板/App.vue';
import '../../界面/常驻面板/panel.css';
/**
 * 面板的 DOM 挂在酒馆主页面, 而 webpack 把样式注进了脚本自己所在的文档,
 * 所以要把这些 style 标签搬一份到父页面的 head. 已经在父页面里的样式不会重复搬运.
 */
function 取父页面文档() {
    try {
        const doc = window.parent?.document;
        return doc && doc !== document ? doc : null;
    }
    catch {
        // 父页面跨域或不可访问时退回脚本自己的文档
        return null;
    }
}
function teleportStyles() {
    const parentDocument = 取父页面文档();
    if (!parentDocument) {
        return () => { };
    }
    const target = parentDocument.head;
    const copies = [];
    for (const style of Array.from(document.querySelectorAll('style'))) {
        if (target.contains(style)) {
            continue;
        }
        const copy = parentDocument.createElement('style');
        copy.setAttribute('data-srl-panel', '1');
        copy.textContent = style.textContent;
        target.appendChild(copy);
        copies.push(copy);
    }
    return () => copies.forEach(copy => copy.remove());
}
function mountPanel() {
    const app = createApp(App).use(createPinia());
    const $app = createScriptIdDiv().appendTo('body');
    const host = $app[0];
    // 万一 jQuery 绑定的是脚本自己的文档, 这里再把容器补搬到酒馆主页面
    const parentDocument = 取父页面文档();
    if (parentDocument && host.ownerDocument !== parentDocument) {
        parentDocument.body.appendChild(host);
    }
    app.mount(host);
    const destroyStyles = teleportStyles();
    // 用原生事件而不是 jQuery, 避免事件被代理到父页面导致卸载逻辑不触发
    window.addEventListener('pagehide', () => {
        app.unmount();
        $app.remove();
        destroyStyles();
    });
}
$(() => errorCatched(mountPanel)());
