 var(--c-rose);\n  stroke-width: 1.6;\n  stroke-linecap: round;\n}\n\n.dock.is-fold .fold {\n  border-color: var(--c-rose-dim);\n  color: var(--c-paper);\n}\n\n.chips {\n  display: flex;\n  gap: 5px;\n  min-width: 0;\n  overflow-x: auto;\n  scrollbar-width: none;\n}\n\n.chips::-webkit-scrollbar {\n  display: none;\n}\n\n.chip {\n  flex: none;\n  padding: 3px 10px;\n  border: 1px solid transparent;\n  background: transparent;\n  color: var(--c-muted);\n  font-family: inherit;\n  font-size: 0.78rem;\n  letter-spacing: 0.08em;\n  cursor: pointer;\n}\n\n.chip:hover {\n  color: var(--c-paper-dim);\n}\n\n.chip.is-on {\n  border-color: var(--c-line);\n  background: var(--c-ink-3);\n  color: var(--c-paper);\n}\n\n.acts {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(148px, 1fr));\n  gap: 6px;\n  max-height: 132px;\n  overflow-y: auto;\n}\n\n.act {\n  display: flex;\n  flex-direction: column;\n  gap: 1px;\n  min-width: 0;\n  padding: 6px 9px;\n  border: 1px solid var(--c-line-soft);\n  border-left: 2px solid var(--c-rose-dim);\n  background: var(--c-ink);\n  color: var(--c-paper-dim);\n  font-family: inherit;\n  font-size: 0.8rem;\n  text-align: left;\n  cursor: pointer;\n  transition:\n    border-color 0.18s ease,\n    color 0.18s ease,\n    background 0.18s ease;\n}\n\n.act:hover:not(:disabled) {\n  border-color: var(--c-rose);\n  background: var(--c-ink-3);\n  color: var(--c-paper);\n}\n\n.act:disabled {\n  opacity: 0.42;\n  cursor: not-allowed;\n}\n\n.act.is-key {\n  border-left-color: var(--c-bronze);\n  background: linear-gradient(90deg, rgba(187, 139, 71, 0.14), var(--c-ink) 72%);\n  color: var(--c-paper);\n}\n\n.act-label {\n  font-weight: 700;\n  overflow-wrap: anywhere;\n}\n\n.act-hint {\n  font-size: 0.68rem;\n  color: var(--c-muted);\n  overflow-wrap: anywhere;\n}\n\n.say {\n  display: flex;\n  align-items: flex-end;\n  gap: 7px;\n}\n\n.say-input {\n  flex: 1 1 auto;\n  min-width: 0;\n  max-height: 110px;\n  padding: 7px 10px;\n  border: 1px solid var(--c-line-soft);\n  background: var(--c-ink);\n  color: var(--c-paper);\n  font-family: inherit;\n  font-size: 0.86rem;\n  line-height: 1.7;\n  resize: none;\n  overflow-y: auto;\n}\n\n.say-input::placeholder {\n  color: var(--c-muted);\n}\n\n.say-input:focus {\n  border-color: var(--c-rose-dim);\n  outline: none;\n}\n\n.say-send,\n.say-stop {\n  flex: none;\n  padding: 7px 16px;\n  border: 1px solid var(--c-rose-dim);\n  background: linear-gradient(90deg, rgba(207, 85, 112, 0.24), var(--c-ink-2) 78%);\n  color: var(--c-paper);\n  font-family: inherit;\n  font-size: 0.82rem;\n  letter-spacing: 0.1em;\n  cursor: pointer;\n}\n\n.say-send:hover:not(:disabled) {\n  border-color: var(--c-rose);\n}\n\n.say-send:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\n.say-stop {\n  border-color: var(--c-line);\n  background: transparent;\n  color: var(--c-muted);\n}\n\n.say-stop:hover {\n  border-color: var(--c-rose);\n  color: var(--c-paper);\n}\n\n@media (max-width: 900px) {\n  .dock {\n    padding: 7px 10px 9px;\n  }\n\n  .acts {\n    grid-template-columns: repeat(auto-fill, minmax(124px, 1fr));\n    max-height: 116px;\n  }\n}\n"],"sourceRoot":""}]);
