/**
 * 玩家行动的统一出口: 行动按钮和自由输入框都走这里.
 * 变量更新仍然只由 AI 按世界书的规则负责, 前端不写回任何数值.
 */
export function useSender() {
    const busy = ref(false);
    const generating = ref(false);
    const locked = computed(() => busy.value || generating.value);
    let 兜底计时器 = 0;
    const 释放 = () => {
        window.clearTimeout(兜底计时器);
        busy.value = false;
    };
    const 发送 = async (原文) => {
        const 文本 = (原文 ?? '').trim();
        if (!文本 || locked.value) {
            return;
        }
        let 酒馆在生成中 = false;
        try {
            酒馆在生成中 = builtin.duringGenerating();
        }
        catch {
            酒馆在生成中 = false;
        }
        if (酒馆在生成中) {
            toastr.info('这一轮还在生成，等它结束。');
            return;
        }
        busy.value = true;
        try {
            await createChatMessages([{ role: 'user', message: 文本 }]);
            await triggerSlash('/trigger');
        }
        catch (错误) {
            释放();
            toastr.error(`没发出去：${错误 instanceof Error ? 错误.message : String(错误)}`);
            return;
        }
        // 生成结束事件是主要解锁手段, 这里只作为卡死时的兜底
        兜底计时器 = window.setTimeout(释放, 120000);
    };
    const 停止生成 = async () => {
        try {
            await triggerSlash('/stop');
        }
        catch {
            // 停不下来就让它自己跑完
        }
        释放();
    };
    const 生成轮询 = window.setInterval(() => {
        try {
            generating.value = builtin.duringGenerating();
        }
        catch {
            generating.value = false;
        }
    }, 1000);
    const 解锁监听 = [
        eventOn(tavern_events.GENERATION_ENDED, 释放),
        eventOn(tavern_events.GENERATION_STOPPED, 释放),
        eventOn(tavern_events.MESSAGE_RECEIVED, 释放),
    ];
    onUnmounted(() => {
        window.clearInterval(生成轮询);
        window.clearTimeout(兜底计时器);
        解锁监听.forEach(句柄 => 句柄.stop());
    });
    return { 发送, 停止生成, locked, busy, generating };
}
